window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[81]={"id":"081","numero":81,"titre":"Altération chronique de la vision","objectifs":[{"id":"81-1","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales étiologies d’altération chronique de la vision","contenu":"<p>Devant une <span class=\"kw-def\">baisse d’acuité visuelle (BAV) progressive</span>, la démarche diagnostique repose sur l’<strong>analyse structurée par segment oculaire</strong> et sur la <span class=\"kw-clinique\">latéralité</span> (uni <span class=\"kw-bio\">vs</span> bilatérale) — qui oriente vers une cause générale ou locale.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Étiologies de BAV progressive — organisées par structure atteinte</h4>\n      <table >\n        <thead><tr><th>Structure</th><th>Étiologies</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Cristallin</strong></span></td>\n            <td><span class=\"kw-def\">Cataracte</span> (étiologie la plus fréquente, voir obj. dédié)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Nerf optique</strong></span></td>\n            <td><span class=\"kw-def\">Glaucome chronique à angle ouvert</span> évolué (BAV souvent bilatérale, voir item 84)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Dystrophies rétiniennes héréditaires</strong></span></td>\n            <td>BAV souvent bilatérale :<br>\n              <strong>Maculopathies héréditaires</strong> : maladie de Stargardt (la plus fréquente), maladie de Best, dystrophie des cônes ;<br>\n              <strong>Dystrophies périphériques</strong> : rétinopathies p<span class=\"kw-chiffre\">igm</span>entaires (héméralopie, ostéoblastes au <span class=\"kw-imagerie\">FO</span>)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Syndrome de l’interface vitréomaculaire</strong></span></td>\n            <td>BAV souvent unilatérale : <span class=\"kw-def\">membranes épimaculaires</span>, <span class=\"kw-def\">trous maculaires</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>DMLA</strong></span></td>\n            <td><span class=\"kw-def\">Stade</span> précoce (drusen) ; formes atrophiques : BAV progressive bilatérale ; formes exsudatives : BAV brutale unilatérale</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Œdèmes maculaires</strong></span></td>\n            <td><span class=\"kw-alerte\">Maculopathie diabétique</span> (souvent bilatérale) ; <span class=\"kw-alerte\">occlusion de la veine centrale de la rétine</span> (généralement unilatérale) ; post-<span class=\"kw-ttt\">chirurgie</span> de cataracte (syndrome d’Irvine-Gass,<span class=\"kw-chiffre\"> 3 %</span> des cas) ; uvéites (postérieures, plus rarement antérieures si chroniques) ; néovaisseaux choroïdiens et intra-rétiniens (DMLA exsudative surtout)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Maculopathies toxiques</strong></span></td>\n            <td>BAV souvent bilatérale ; médicaments en cause : <span class=\"kw-ttt\">antipaludéens de synthèse (APS)</span>, <span class=\"kw-ttt\">inhibiteurs MEK</span>, <span class=\"kw-ttt\">nitrite d’alkyle (« poppers »)</span> — voir obj. dédié</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche pratique.</strong> Devant une BAV progressive, la séquence d’examen est : <strong>1)</strong> mesure de l’acuité visuelle de loin <em>et</em> de près ; <strong>2)</strong> examen à la lampe à fente après dilatation (recherche d’une cataracte ++) ; <strong>3)</strong> mesure du tonus oculaire (recherche d’un glaucome) ; <strong>4)</strong> fond d’œil dilaté (DMLA, dystrophies, <span class=\"kw-clinique\">œdème</span> maculaire) ; <strong>5)</strong> <span class=\"kw-imagerie\">OCT</span> maculaire (examen-clé devant tout syndrome maculaire).\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 84 — Glaucome chronique · 247 — Rétinopathie diabétique</em></p>","frequence":3},{"id":"81-2","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître la séméiologie et les moyens de dépistage d’un syndrome maculaire","contenu":"<p>Le <span class=\"kw-def\">syndrome maculaire</span> traduit une atteinte de la <span class=\"kw-clinique\">macula</span> (zone centrale de la rétine, responsable de la vision fine et de la lecture). C’est un syndrome <strong>clinique</strong>, à reconnaître pour orienter vers une cause maculaire (DMLA, <span class=\"kw-clinique\">œdème</span> maculaire, maculopathie <span class=\"kw-etio\">toxique</span>, membrane épimaculaire…).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tétrade clinique du syndrome maculaire</h4>\n      <table >\n        <thead><tr><th>Symptôme</th><th>Description</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>BAV</strong></span></td>\n            <td>De loin <strong>et</strong> de près. Progressive (atrophique, <span class=\"kw-etio\">toxique</span>) ou brutale (exsudative, hémorragie maculaire).</td>\n            <td>Atteinte des photorécepteurs maculaires (cônes ++)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Scotome central</strong></span> ou paracentral</td>\n            <td>Tache aveugle au centre du champ visuel. Profond aux stades évolués.</td>\n            <td>Atrophie des photorécepteurs et/ou de l’EP rétinien</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Métamorphopsies</strong></span></td>\n            <td>Déformation des lignes droites (ondulations, lettres qui « dansent »).</td>\n            <td>Soulèvement de la rétine maculaire par <span class=\"kw-clinique\">les</span> néovaisseaux ou un <span class=\"kw-clinique\">œdème</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Dyschromatopsie bleu-jaune</strong></span></td>\n            <td>Trouble de la vision des couleurs dans l’axe bleu-jaune.</td>\n            <td>Caractéristique des atteintes maculaires (à distinguer de la dyschromatopsie rouge-vert des neuropathies optiques)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Exception sémiologique à connaître.</strong> La <span class=\"kw-def\">maladie de Stargardt</span> (maculopathie <span class=\"kw-etio\">héréditaire</span>) donne une <span class=\"kw-clinique\">dyschromatopsie rouge-vert</span> — c’est une <strong>exception</strong> à la règle « atteinte maculaire = bleu-jaune ». À l’inverse, <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">neuropathies optiques</span> (NORB…) donnent une dyschromatopsie rouge-vert.\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Moyens de <span class=\"kw-def\">dépistage</span> — outils cliniques au cabinet</h4>\n      <table >\n        <thead><tr><th>Outil</th><th>Principe</th><th>Ce qu’on cherche</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Acuité visuelle</strong></span> (loin et près)</td>\n            <td>Échelle de Monoyer (loin) et Parinaud (près)</td>\n            <td>BAV bilatérale et symétrique souvent, mais <span class=\"kw-clinique\">asymétrie</span> possible</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Grille d’Amsler</strong></span></td>\n            <td>Quadrillage régulier examiné monoculairement</td>\n            <td><span class=\"kw-clinique\">Scotome central</span> (zone manquante) et <span class=\"kw-clinique\">métamorphopsies</span> (lignes ondulées)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Vision des couleurs</strong></span></td>\n            <td>Test de Farnsworth ou planches d’Ishihara</td>\n            <td>Dyschromatopsie bleu-jaune (axe « tritan »)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Fond d’œil dilaté</strong></span></td>\n            <td>Biomicroscopie LAF après dilatation pupillaire ou photographie en couleurs</td>\n            <td>Drusen · altérations p<span class=\"kw-chiffre\">igm</span>entaires · hémorragies · exsudats · <span class=\"kw-clinique\">œdème</span> maculaire · décollement exsudatif</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>OCT maculaire</strong></span></td>\n            <td>Coupe B-scan de la macula (non irradiant, non invasif)</td>\n            <td>Examen <strong>incontournable</strong> ++ : atrophie de l’EP, <span class=\"kw-clinique\">œdème</span>, liquide intra/sous-rétinien, décollement de l’EP, néovaisseaux choroïdiens</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Auto-<span class=\"kw-def\">dépistage</span> par la grille d’Amsler.</strong> Tout patient porteur de drusen (MLA) doit recevoir une <strong>grille d’Amsler</strong> à conserver chez lui et l’examiner régulièrement <em>monoculairement</em> (un œil à la fois). L’apparition <strong>brutale</strong> d’un scotome ou de métamorphopsies impose une consultation ophtalmologique <span class=\"kw-alerte\">en urgence (&lt; 48 h)</span> pour rechercher des néovaisseaux choroïdiens à traiter immédiatement (DMLA exsudative).\n      </div>","frequence":4},{"id":"81-3","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités de l’interprétation d’un réflexe photomoteur direct et consensuel (voir item 82)","contenu":"<p>Le <span class=\"kw-def\">réflexe photomoteur</span> est un réflexe d’adaptation pupillaire à la lumière, qui teste l’intégrité de la <span class=\"kw-clinique\">voie afférente</span> (rétine → nerf optique → bandelette optique → mésencéphale) et de la <span class=\"kw-clinique\">voie efférente</span> (noyau d’Edinger-Westphal → III → ganglion ciliaire → sphincter irien).</p>\n\n      <ul>\n        <li><strong>Photomoteur direct</strong> : on éclaire un œil, la pupille de <em>cet œil</em> se contracte (myosis).</li>\n        <li><strong>Photomoteur consensuel</strong> : on éclaire un œil, la pupille de <em>l’œil controlatéral</em> se contracte également (myosis).</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Renvoi item 82.</strong> L’interprétation détaillée des anomalies du réflexe photomoteur (DPAR / signe de Marcus-Gunn dans la neuropathie optique, mydriase aréactive dans l’atteinte du III…) relève de l’<strong>item 82 — Anomalie aiguë de la vision</strong>. Voir la fiche dédiée pour la sémiologie complète et l’interprétation au lit du malade.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision</em></p>","frequence":0},{"id":"81-4","rang":"A","rubrique":"Contenu multimédia","titre":"Interpréter un réflexe photomoteur direct et consensuel (voir item 82)","contenu":"<p>Objectif <strong>pratique</strong> : interpréter au lit du malade une anomalie du réflexe photomoteur. L’examen se fait en pénombre, en éclairant un œil après l’autre avec une source lumineuse vive, et en observant la pupille éclairée (direct) puis la pupille controlatérale (consensuel).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Patrons d’interprétation typiques (à connaître)</h4>\n      <table >\n        <thead><tr><th>Anomalie</th><th>Direct</th><th>Consensuel</th><th>Mécanisme</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Atteinte afférente</strong></span> (voie sensorielle : nerf optique, rétine)</td>\n            <td>Aboli/diminué côté atteint</td>\n            <td>Aboli/diminué côté sain (quand on éclaire le côté atteint)</td>\n            <td>Pas de message visuel → pas de réflexe ni direct ni consensuel</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Atteinte efférente</strong></span> (voie motrice : III, sphincter irien)</td>\n            <td>Aboli côté atteint</td>\n            <td>Aboli côté atteint (quand on éclaire le côté sain)</td>\n            <td>La pupille atteinte ne peut plus se contracter, quel que soit l’œil éclairé</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-alerte\"><strong>DPAR</strong></span> (signe de Marcus-Gunn)</td>\n            <td>Au test alternant : la pupille atteinte se <strong>dilate</strong> paradoxalement quand on l’éclaire</td>\n            <td>—</td>\n            <td><span class=\"kw-clinique\">Asymétrie</span> d’information afférente entre <span class=\"kw-clinique\">les</span> 2 yeux → neuropathie optique unilatérale ou asymétrique</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Contenu détaillé renvoyé à l’item 82.</strong> L’interprétation fine du réflexe photomoteur, ses pièges (mydriase pharmacologique, atteinte du sympathique cervical avec <span class=\"kw-clinique\">syndrome de Claude</span>-Bernard-Horner…) et son intégration dans le bilan d’une anomalie aiguë de la vision relèvent de l’<strong>item 82 — Anomalie aiguë de la vision</strong>. Se référer à la fiche dédiée pour la sémiologie complète et <span class=\"kw-clinique\">les</span> arbres décisionnels.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pas d’image médicale dans <span class=\"kw-clinique\">les</span> fiches sources.</strong> Aucune image illustrative du réflexe photomoteur n’a été trouvée dans le dossier <code>fiches sources/81/</code>. Kevin pourra enrichir cet objectif manuellement (schéma ou photo de mydriase aréactive / DPAR) si nécessaire.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision</em></p>","frequence":1},{"id":"81-5","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les principaux examens complémentaires en ophtalmologie et leurs indications","contenu":"<p><span class=\"kw-clinique\">Les</span> examens complémentaires en ophtalmologie sont nombreux ; leur choix dépend de la <strong>structure suspectée</strong> et de la question posée (<span class=\"kw-def\">diagnostic positif</span>, <span class=\"kw-def\">suivi</span>, bilan pré-chirurgical).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Imagerie maculaire — pierre angulaire du diagnostic des pathologies maculaires</h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Principe</th><th>Indications principales</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>OCT maculaire</strong></span><br>(tomographie en cohérence optique)</td>\n            <td>Coupe B-scan non invasive, non irradiante, en quelques secondes</td>\n            <td><strong>Examen incontournable</strong> ++ pour : DMLA (atrophie de l’EP, <span class=\"kw-clinique\">œdème</span>, liquide, décollement de l’EP, néovaisseaux choroïdiens), <span class=\"kw-clinique\">œdème</span> maculaire, membrane épimaculaire, trou maculaire (mesure de la taille)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>Angiographie du fond d’œil</strong></span></td>\n            <td>Clichés du <span class=\"kw-imagerie\">FO</span> après injection IV d’un colorant fluorescent : <span class=\"kw-ttt\">fluorescéine</span> (le plus utilisé) ou <span class=\"kw-ttt\">vert d’indocyanine</span> (pour visualiser la circulation choroïdienne)</td>\n            <td>Néovaisseaux choroïdiens (DMLA exsudative) : hyperfluorescence maculaire à la phase tardive · occlusions vasculaires rétiniennes · rétinopathie diabétique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-imagerie\"><strong>OCT-A</strong></span><br>(angio-<span class=\"kw-imagerie\">OCT</span>)</td>\n            <td>Visualisation de la vascularisation rétinienne et choroïdienne <strong>sans injection</strong> de colorant</td>\n            <td>Largement utilisée pour le diagnostic et le <span class=\"kw-def\">suivi</span> de la DMLA. Avantage : pas d’<span class=\"kw-ci\">allergie</span> liée à la fluorescéine.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Examens fonctionnels — caractérisation et <span class=\"kw-def\">suivi</span></h4>\n      <table >\n        <thead><tr><th>Examen</th><th>Indications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Champ visuel automatisé</strong></span> (Humphrey)</td>\n            <td>Glaucome chronique (<span class=\"kw-def\">suivi</span> du déficit) · <span class=\"kw-bio\">CV</span> des 10° centraux pour la <span class=\"kw-def\">surveillance</span> des APS (scotomes juxtamaculaires)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>ERG multifocal</strong></span></td>\n            <td><span class=\"kw-def\">Surveillance</span> des maculopathies toxiques aux APS (diminution des réponses périfovéolaires précoce)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>FO en autofluorescence</strong></span> (lumière bleue)</td>\n            <td>DMLA atrophique (plages d’atrophie en taches sombres) · maculopathies toxiques</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Test de la vision des couleurs</strong></span><br>(Farnsworth, Ishihara)</td>\n            <td>Dyschromatopsie bleu-jaune (maculaire) <span class=\"kw-bio\">vs</span> rouge-vert (neuropathie optique)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-clinique\"><strong>Grille d’Amsler</strong></span></td>\n            <td><span class=\"kw-def\">Dépistage</span> et auto-<span class=\"kw-def\">surveillance</span> d’un scotome central et de métamorphopsies (MLA / DMLA)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-imagerie\">Échographie</span> oculaire</h4>\n      <ul>\n        <li><span class=\"kw-imagerie\"><strong>Mode B</strong></span> : utile en cas de <span class=\"kw-clinique\">cataracte dense avec FO inaccessible</span> → élimine un <span class=\"kw-alerte\">décollement de rétine</span> ou une <span class=\"kw-alerte\">tumeur intra-oculaire</span>.</li>\n        <li><span class=\"kw-imagerie\"><strong>Mode A</strong></span> (biométrie ultrasonore axiale) : mesure de la longueur axiale de l’œil, utilisée si perte de transparence des milieux optiques (cicatrice cornéenne, cataracte très évoluée).</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Bilan pré-chirurgical de cataracte</h4>\n      <ul>\n        <li><span class=\"kw-clinique\"><strong>Kératométrie</strong></span> = puissance réfractive de la cornée (≈ <span class=\"kw-chiffre\">42 dioptries</span> normalement)</li>\n        <li><span class=\"kw-imagerie\"><strong>Biométrie optique non contact par interférométrie</strong></span> +++ (méthode de référence pour la longueur axiale)</li>\n        <li><span class=\"kw-imagerie\">Échographie</span> mode A (biométrie ultrasonore axiale) : moins précise, utilisée si milieux non transparents</li>\n        <li>Ces données permettent de calculer la <span class=\"kw-ttt\">puissance sphérique de l’implant intra-oculaire</span> ; pour <span class=\"kw-clinique\">les</span> implants toriques (correction d’ast<span class=\"kw-chiffre\">igm</span>atisme), calcul supplémentaire de la puissance cylindrique</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Stratégie d’imagerie devant une BAV chronique.</strong> En 1ʳᵉ intention après la clinique : <span class=\"kw-imagerie\">OCT maculaire</span> (rendement diagnostique élevé, non invasif). En 2ᵉ intention selon l’orientation : <span class=\"kw-imagerie\">angiographie à la fluorescéine</span> ou <span class=\"kw-imagerie\">OCT-A</span> pour caractériser des néovaisseaux. L’<span class=\"kw-imagerie\">échographie B</span> reste réservée aux situations où le <span class=\"kw-imagerie\">FO</span> n’est pas accessible (cataracte dense, hémorragie du vitré).\n      </div>","frequence":2},{"id":"81-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la dégénérescence maculaire liée à l’âge (DMLA)","contenu":"<p>La <span class=\"kw-def\">dégénérescence maculaire liée à l’âge (DMLA)</span> est une affection rétinienne <strong>dégénérative</strong> de la <span class=\"kw-clinique\">région maculaire</span>, touchant <span class=\"kw-clinique\">les</span> patients de <span class=\"kw-chiffre\">&gt; 50 ans</span>. Elle représente la <span class=\"kw-alerte\">1ʳᵉ cause de malvoyance après 50 ans dans les pays industrialisés</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">MLA <span class=\"kw-bio\">vs</span> DMLA — bien <span class=\"kw-clinique\">les</span> distinguer</h4>\n      <table >\n        <thead><tr><th></th><th>Maculopathie liée à l’âge (MLA)</th><th>Dégénérescence maculaire liée à l’âge (DMLA)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Stades</strong></td>\n            <td>Stades <span class=\"kw-def\">débutants</span></td>\n            <td>Stades <span class=\"kw-def\">évolués</span> (atrophique et/ou exsudative — peuvent coexister)</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>Pas ou peu de retentissement fonctionnel (AV normale ou peu abaissée). Intérêt du <span class=\"kw-clinique\">dépistage</span>.</td>\n            <td>Forme symptomatique : <span class=\"kw-clinique\">BAV</span> (progressive si atrophique, brutale si exsudative) + <span class=\"kw-clinique\">métamorphopsies</span> (surtout exsudative).</td>\n          </tr>\n          <tr>\n            <td><strong>Anomalies rétiniennes</strong></td>\n            <td><span class=\"kw-clinique\">Drusen</span> (dépôts lipidiques sous l’EP rétinien) + altérations p<span class=\"kw-chiffre\">igm</span>entaires (prolifération + atrophie de l’EP)</td>\n            <td>Forme <span class=\"kw-def\">atrophique</span> (« sèche ») et/ou <span class=\"kw-def\">exsudative</span> ou néovasculaire (« humide »)</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span> <span class=\"kw-chiffre\">≥ 50 ans</span></strong></td>\n            <td><span class=\"kw-chiffre\">17,5 %</span></td>\n            <td><span class=\"kw-chiffre\">0,5 %</span> ;<span class=\"kw-chiffre\"> 0,1 %</span> entre <span class=\"kw-chiffre\">55-59 ans</span> ; <span class=\"kw-chiffre\">10 % après 85 ans</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Les</span> 2 formes évoluées de DMLA</h4>\n      <ul>\n        <li><span class=\"kw-def\"><strong>Forme atrophique</strong></span> (« forme sèche ») : <span class=\"kw-clinique\">disparition progressive des cellules de l’EP</span> avec photorécepteurs sus-jacents et choriocapillaire sous-jacente. <strong>Plus fréquente</strong> que la forme exsudative. <span class=\"kw-clinique\">Évolution</span> <span class=\"kw-chiffre\">très progressive</span> mais <span class=\"kw-alerte\">inexorable</span> vers une BAV sévère avec scotome central.</li>\n        <li><span class=\"kw-def\"><strong>Forme exsudative ou néovasculaire</strong></span> (« forme humide ») : <span class=\"kw-clinique\">néovaisseaux choroïdiens</span> qui se développent sous l’EP puis sous la rétine maculaire, à l’origine d’<span class=\"kw-clinique\">œdème</span> maculaire, liquide intra/sous-rétinien, décollement de l’EP, hémorragies. <span class=\"kw-def\">Prévalence</span> à<span class=\"kw-chiffre\"> 1 %</span> pour <span class=\"kw-clinique\">les</span> cas traités après <span class=\"kw-chiffre\">50 ans</span> · <span class=\"kw-alerte\">risque de bilatéralisation 50 % à 5 ans</span>.</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Histoire naturelle.</strong> La MLA n’évolue <em>pas obl<span class=\"kw-chiffre\">iga</span>toirement</em> vers une DMLA, mais c’est possible. Lorsque la DMLA s’installe, <span class=\"kw-clinique\">les</span> 2 formes peuvent <strong>coexister</strong> sur le même œil ou sur les 2 yeux.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 82 — Anomalie aiguë de la vision · 84 — Glaucome chronique</em></p>","frequence":1},{"id":"81-7","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la DMLA","contenu":"<p>La DMLA est la <span class=\"kw-alerte\">1ʳᵉ cause de malvoyance après 50 ans</span> dans <span class=\"kw-clinique\">les</span> pays industrialisés. <span class=\"kw-def\">Prévalence</span> globale : <span class=\"kw-chiffre\">18 % après 50 ans</span> et <span class=\"kw-chiffre\">25 % après 75 ans</span> (toutes formes confondues : MLA + DMLA).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Prévalence</span> par <span class=\"kw-def\">stade</span> et par âge</h4>\n      <table >\n        <thead><tr><th>Stade</th><th><span class=\"kw-chiffre\">≥ 50 ans</span></th><th><span class=\"kw-chiffre\">55-59 ans</span></th><th>&gt;<span class=\"kw-chiffre\"> 85 ans</span></th></tr></thead>\n        <tbody>\n          <tr><td><strong>MLA</strong> (<span class=\"kw-def\">stade</span> débutant)</td><td><span class=\"kw-chiffre\">17,5 %</span></td><td>—</td><td>—</td></tr>\n          <tr><td><strong>DMLA évoluée</strong></td><td><span class=\"kw-chiffre\">0,5 %</span></td><td><span class=\"kw-chiffre\">0,1 %</span></td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> non modifiables</h4>\n      <ul>\n        <li><strong>Âge</strong> : <span class=\"kw-def\">prévalence</span> augmente avec l’âge</li>\n        <li><strong>Ethnie</strong> : populations <span class=\"kw-clinique\">européennes</span> <span class=\"kw-clinique\">les</span> plus à risque</li>\n        <li><strong>Facteurs familiaux</strong></li>\n        <li>Forte association avec le <span class=\"kw-bio\">polymorphisme du facteur H du complément</span> (gène situé sur le chromosome 1)</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-def\">Facteurs de risque</span> modifiables (à cibler en prévention)</h4>\n      <ul>\n        <li><span class=\"kw-alerte\"><strong>Tabac</strong></span> : <span class=\"kw-chiffre\">×3</span> le risque, voire <span class=\"kw-chiffre\">×5</span> chez le très grand fumeur. Risque qui <strong>persiste plusieurs années après l’arrêt</strong>.</li>\n        <li><span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">obésité</span></li>\n        <li><span class=\"kw-etio\">Exposition solaire</span></li>\n        <li>Régime <span class=\"kw-clinique\">pauvre en anti-oxydants</span>, <span class=\"kw-clinique\">riche en acides gras saturés et cholestérol</span></li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Facteur protecteur — régime « méditerranéen ».</strong> Riche en <span class=\"kw-clinique\">légumes verts</span>, en <span class=\"kw-clinique\">poisson</span> et utilisant l’<span class=\"kw-clinique\">huile d’olive</span> — conseillé en prévention. Au <span class=\"kw-def\">stade</span> MLA, une supplémentation per os quotidienne en <span class=\"kw-ttt\">vitamine E + vitamine C + zinc + lutéine + zéaxanthine</span> retarde l’<span class=\"kw-clinique\">évolution</span> vers <span class=\"kw-clinique\">les</span> formes évoluées (à doses bien définies). L’<span class=\"kw-ttt\">addition d’oméga-3 et de bêta-carotène</span> <strong>ne réduit pas</strong> ❌ le risque de progression.\n      </div>","frequence":1},{"id":"81-8","rang":"B","rubrique":"Diagnostic positif","titre":"Connaître les pathologies maculaires chroniques hors DMLA (membrane épirétinienne, trou maculaire, œdème maculaire)","contenu":"<p>En dehors de la DMLA, trois grandes entités regroupent <span class=\"kw-clinique\">les</span> <strong>pathologies maculaires chroniques</strong> : les <span class=\"kw-def\">membranes épimaculaires</span>, les <span class=\"kw-def\">trous maculaires</span> (tous deux relevant des syndromes de l’interface vitréomaculaire) et les <span class=\"kw-def\">œdèmes maculaires</span>.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Syndromes de l’interface vitréomaculaire — physiopath</h4>\n      <p>Vers la <strong>cinquantaine</strong>, le vitré postérieur se détache normalement de la région maculaire. Dans ces syndromes, c’est l’<span class=\"kw-clinique\">adhérence pathologique du vitré postérieur à la région maculaire</span> qui est à l’origine des lésions. <span class=\"kw-def\">Terrain</span> : <strong>idiopathique chez le sujet âgé</strong> ; chez le sujet jeune, surtout après <span class=\"kw-clinique\">traumatisme</span>, <span class=\"kw-clinique\">déchirure rétinienne</span> ou <span class=\"kw-clinique\">inflammation endo-oculaire sévère</span>. Latéralité <strong>souvent unilatérale</strong>, mais bilatéralité possible.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Membranes épimaculaires <span class=\"kw-bio\">vs</span> trous maculaires</h4>\n      <table >\n        <thead><tr><th></th><th>Membranes épi- ou prémaculaires</th><th>Trous maculaires (moins fréquents)</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Séparation du vitré postérieur de la région maculaire associée à la <span class=\"kw-clinique\">prolifération d’un tissu fibreux à la surface de la macula</span></td>\n            <td><span class=\"kw-clinique\">Perte de la continuité du tissu neurosensoriel maculaire</span> par écartement des berges fovéolaires</td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>Soit pauci-symptomatiques, soit <span class=\"kw-clinique\">BAV et/ou métamorphopsies</span> si <span class=\"kw-clinique\">les</span> membranes se rétractent</td>\n            <td>Installation rapide : <span class=\"kw-clinique\">BAV + scotome central + métamorphopsies</span> souvent associées</td>\n          </tr>\n          <tr>\n            <td><strong>Fond d’œil</strong></td>\n            <td>Aspect brillant « <em>reflet cellophane</em> », distorsion du tissu rétinien adjacent et des vaisseaux</td>\n            <td><span class=\"kw-clinique\">Lésion</span> <span class=\"kw-clinique\">orangée foncée, arrondie, à bords nets</span></td>\n          </tr>\n          <tr>\n            <td><strong>Examen-clé</strong></td>\n            <td><span class=\"kw-imagerie\">OCT maculaire</span> : augmentation secondaire de l’épaisseur rétinienne (reflète le degré de contraction)</td>\n            <td><span class=\"kw-imagerie\">OCT</span> confirme le diagnostic, mesure la taille du trou et pose l’indication chirurgicale</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement</strong></td>\n            <td>Si BAV importante : « <span class=\"kw-ttt\">pelage</span> » chirurgical par <span class=\"kw-ttt\">vitrectomie</span></td>\n            <td><span class=\"kw-ttt\">Vitrectomie</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-clinique\">Œdèmes</span> maculaires — caractéristiques générales</h4>\n      <ul>\n        <li><strong>Caractéristique</strong> : <span class=\"kw-clinique\">augmentation de l’épaisseur maculaire</span></li>\n        <li><strong>Symptômes</strong> : <span class=\"kw-clinique\">BAV</span> (en général progressive) + <span class=\"kw-clinique\">métamorphopsies</span> (insidieuses si cause chronique, aiguës si apparition brutale)</li>\n        <li><strong>Fond d’œil</strong> : aspect d’<span class=\"kw-clinique\">œdème maculaire cystoïde</span> si <span class=\"kw-clinique\">œdème</span> important → image typique « en pétales de fleur »</li>\n        <li><strong><span class=\"kw-imagerie\">OCT</span></strong> : kystes intra-rétiniens nettement individualisables</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principales étiologies d’<span class=\"kw-clinique\">œdème</span> maculaire et leur PEC</h4>\n      <table >\n        <thead><tr><th>Étiologie</th><th>Particularités</th><th>Traitement</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Maculopathie diabétique</strong></span></td>\n            <td>Principale cause de malvoyance chez <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">DT2</span></td>\n            <td>Équilibre des facteurs systémiques (<span class=\"kw-clinique\">HTA</span>) ; IVT <span class=\"kw-ttt\">anti-VEGF</span> ou <span class=\"kw-ttt\">corticoïdes (dexaméthasone)</span> ; photocoagulation au <span class=\"kw-ttt\">laser</span> focal</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>OVCR / OBVCR</strong></span></td>\n            <td>Forme œdémateuse</td>\n            <td>IVT <span class=\"kw-ttt\">anti-VEGF</span> et/ou <span class=\"kw-ttt\">corticoïdes</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Post-chirurgie de cataracte</strong></span><br>(<span class=\"kw-def\">syndrome d’Irvine-Gass</span>)</td>\n            <td>Origine <span class=\"kw-etio\">inflammatoire</span>, survient dans <span class=\"kw-clinique\">les</span> <strong>semaines ou mois</strong> qui suivent la <span class=\"kw-ttt\">chirurgie</span> (<span class=\"kw-chiffre\">3 %</span>). BAV de loin et de près + métamorphopsies. Peut régresser (2/3) ou évoluer vers un <span class=\"kw-clinique\">œdème</span> maculaire chronique.</td>\n            <td>Anti-inflammatoires locaux (<span class=\"kw-ttt\">AINS + stéroïdiens</span>) + <span class=\"kw-ttt\">acétazolamide</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Uvéites</strong></span></td>\n            <td>Postérieures ++ (plus rarement antérieures si chroniques). Une des principales causes de BAV permanente au cours des uvéites postérieures.</td>\n            <td>Traitement de la cause ; si non infectieuse : anti-inflammatoires systémiques (<span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">immunosuppresseurs</span>) ou IVT <span class=\"kw-ttt\">corticoïdes</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Néovaisseaux choroïdiens / intra-rétiniens</strong></span></td>\n            <td>Principale cause = <span class=\"kw-alerte\">DMLA exsudative</span>. BAV aiguës ou rapidement progressives + métamorphopsies.</td>\n            <td><span class=\"kw-alerte\">Urgence thérapeutique 🔥</span> : IVT <span class=\"kw-ttt\">anti-VEGF</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tableau récapitulatif de la PEC des principales causes</h4>\n      <table >\n        <thead>\n          <tr><th>Traitement</th><th>DMLA exsudative</th><th>OVCR</th><th>Rétinopathie diabétique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><span class=\"kw-ttt\">Anti-VEGF IVT</span></td><td>✅</td><td>✅</td><td>✅</td></tr>\n          <tr><td><span class=\"kw-ttt\">Corticoïdes IVT</span></td><td>—</td><td>✅</td><td>✅</td></tr>\n          <tr><td><span class=\"kw-ttt\">Photocoagulation laser focal</span></td><td>—</td><td>—</td><td>✅</td></tr>\n          <tr><td><span class=\"kw-ttt\">Thérapie photodynamique</span></td><td>✅</td><td>—</td><td>—</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Dystrophies rétiniennes héréditaires — à connaître pour le <span class=\"kw-def\">diagnostic différentiel</span>.</strong> Affections dégénératives des photorécepteurs et/ou de l’EP, le plus souvent <strong>bilatérales</strong>, à tout âge, transmission variable. Deux grands types : <strong>périphériques</strong> (atteinte prédominante des bâtonnets) → <span class=\"kw-clinique\">rétinopathies pigmentaires</span> (héméralopie, <span class=\"kw-bio\">CV</span> tubulaire au <span class=\"kw-def\">stade</span> évolué, aspect en « pseudo-ostéoblastes » au <span class=\"kw-imagerie\">FO</span>) ; <strong>maculaires</strong> (atteinte prédominante des cônes) → <span class=\"kw-clinique\">maladie de Stargardt</span> (la plus fréquente, autosomique récessive, début <span class=\"kw-chiffre\">7-12 ans</span>, aspect « œil de bœuf » au <span class=\"kw-imagerie\">FO</span>, dyschromatopsie rouge-vert exceptionnelle), maladie de Best, dystrophie des cônes.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 247 — Rétinopathie diabétique</em></p>","frequence":4},{"id":"81-9","rang":"A","rubrique":"Définition","titre":"Connaître la définition de la cataracte, ses principales causes, et les modalités de diagnostic clinique","contenu":"<p>La <span class=\"kw-def\">cataracte</span> = <strong>opacification de tout ou partie du <span class=\"kw-clinique\">cristallin</span></strong>. Pathologie <span class=\"kw-chiffre\">très fréquente</span> et <strong>en augmentation</strong> (vieillissement de la population) : touche <span class=\"kw-chiffre\">≥ 1/5 des patients de &gt; 65 ans</span> et <span class=\"kw-chiffre\">2/3 des &gt; 85 ans</span>. Sa <span class=\"kw-ttt\">chirurgie</span> est la <strong>chirurgie la plus fréquente toutes spécialités confondues</strong> (environ <span class=\"kw-chiffre\">800 000/an</span> en France).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Tableau clinique de BAV typique</h4>\n      <ul>\n        <li><strong>Mode d’installation</strong> : <span class=\"kw-clinique\">progressive</span></li>\n        <li><strong>Latéralité</strong> : <span class=\"kw-clinique\">bilatérale</span>, parfois légèrement asymétrique</li>\n        <li><strong>BAV prédomine en vision de loin</strong> ; acuité visuelle de près souvent relativement conservée ⚠️ <em>sauf si <span class=\"kw-alerte\">cataracte sous-capsulaire postérieure</span></em></li>\n        <li><span class=\"kw-clinique\">Myopie d’indice</span> : augmentation de l’indice de réfraction du cristallin → <strong>diminution du besoin de porter <span class=\"kw-clinique\">les</span> verres correcteurs en vision de près</strong> (« le patient lit à nouveau sans lunettes »)</li>\n      </ul>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Autres signes fonctionnels</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Diplopie monoculaire</span> dans la cataracte nucléaire (plus rare)</li>\n        <li>Modification de la perception des couleurs avec <span class=\"kw-clinique\">jaunissement</span> des couleurs (souvent perçu après <span class=\"kw-ttt\">chirurgie</span> du 1ᵉʳ œil)</li>\n        <li><span class=\"kw-clinique\">Photophobie</span> avec halos colorés autour des lumières (diffraction au niveau des opacités) → <strong>gêne à la conduite automobile de nuit</strong>, éblouissement par <span class=\"kw-clinique\">les</span> phares</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Diagnostic = clinique pur.</strong> Le diagnostic de cataracte est <span class=\"kw-def\">clinique</span> et ne requiert <span class=\"kw-alerte\">aucun examen complémentaire</span> ❌. L’examen-clé est la <span class=\"kw-clinique\">lampe à fente après dilatation pupillaire</span> qui montre la perte de transparence cristallinienne avec aspect opalescent, parfois coloration brun-jaunâtre, et précise la <strong>répartition anatomique des opacités</strong> (= type de cataracte).\n      </div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Types de cataracte à la lampe à fente</h4>\n      <table >\n        <thead><tr><th>Type</th><th>LAF</th><th>Particularités cliniques</th><th>Étiologie typique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Nucléaire</strong></span></td>\n            <td>Atteinte du noyau cristallinien (opacification centrale)</td>\n            <td>BAV de loin · <span class=\"kw-clinique\">myopie d’indice</span></td>\n            <td>Liée à l’<span class=\"kw-etio\">âge ++</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Corticale</strong></span></td>\n            <td>Opacification périphérique au niveau du cortex cristallinien ; opacité « en cavaliers »</td>\n            <td>Peu de BAV ; éblouissement et photophobie</td>\n            <td>—</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Sous-capsulaire postérieure</strong></span></td>\n            <td>Opacification en soucoupe devant la capsule postérieure</td>\n            <td><span class=\"kw-alerte\">Gêne de loin <em>et</em> de près</span> ⚠️</td>\n            <td>Métabolique · <span class=\"kw-etio\">iatrogène</span> · traumatisme par contusion</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\"><strong>Totale</strong></span></td>\n            <td>Cataracte <strong>très évoluée</strong>, visible à l’œil nu (aire pupillaire blanche)</td>\n            <td>—</td>\n            <td>—</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Principales causes de cataracte (à mémoriser pour l’EDN)</h4>\n      <table >\n        <thead><tr><th>Famille étiologique</th><th>Détail</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Sénile (âge)</strong></span></td>\n            <td>Étiologie <strong>la plus fréquente</strong>, le plus souvent <span class=\"kw-clinique\">bilatérale et globalement symétrique</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Contusion traumatique</strong></span></td>\n            <td>Contusion violente à globe fermé. Délai d’apparition : des <span class=\"kw-chiffre\">heures</span> à <span class=\"kw-chiffre\">plusieurs années après</span>. Type souvent <span class=\"kw-clinique\">sous-capsulaire postérieur</span> (aspect en rosace).</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Traumatisme perforant</strong></span></td>\n            <td>Contexte évocateur le plus souvent, mais possibles passages inaperçus (enfant ++). Rechercher un <span class=\"kw-alerte\">corps étranger intra-oculaire</span> par <span class=\"kw-imagerie\">RX ou TDM de l’orbite</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Ophtalmologique</strong></span></td>\n            <td>Uvéite chronique (surtout postérieure, <span class=\"kw-ttt\">corticothérapie</span> prolongée &gt;<span class=\"kw-chiffre\"> 3 mois</span> — ex. <span class=\"kw-clinique\">sarcoïdose</span>) · myopie forte (&gt; 6 dioptries) · rétinopathies p<span class=\"kw-chiffre\">igm</span>entaires · ATCD de <span class=\"kw-ttt\">chirurgie</span> oculaire (DR, vitrectomie, chirurgie filtrante du glaucome)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Métabolique</strong></span></td>\n            <td><span class=\"kw-clinique\">Diabète</span> · hypoparathyroïdie · hypercorticisme · hypocalcémie chronique</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Iatrogène</strong></span></td>\n            <td><span class=\"kw-ttt\">Corticoïdes locaux ou généraux au long cours</span> (forme <span class=\"kw-clinique\">sous-capsulaire postérieure</span>) · <span class=\"kw-ttt\">radiothérapie</span> orbitaire (<span class=\"kw-clinique\">mélanome</span> choroïdien, tumeur de l’orbite)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Génétique</strong></span></td>\n            <td><span class=\"kw-clinique\">Trisomie 21</span> · dystrophie myotonique de Steinert (cataracte + ptosis + troubles moteurs + trouble du rythme cardiaque)</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-etio\"><strong>Congénital</strong></span></td>\n            <td>Embryofoetopathie (<span class=\"kw-clinique\">rubéole congénitale ++</span>) · héréditaires</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Au terme de la LAF, 3 questions clés.</strong>\n        <ul style=\"margin:6px 0 0 0;\">\n          <li>L’opacification du cristallin est-elle <strong>responsable</strong> de la BAV ?</li>\n          <li>La gêne ressentie fait-elle poser une <strong>indication chirurgicale</strong> ?</li>\n          <li>Existe-t-il une <strong>autre pathologie oculaire</strong> (DMLA, glaucome…) qui risque de compromettre le résultat postopératoire ?</li>\n        </ul>\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 84 — Glaucome chronique</em></p>","frequence":6},{"id":"81-10","rang":"B","rubrique":"Epidémiologie","titre":"Connaître l’épidémiologie de la cataracte","contenu":"<p>La cataracte est une pathologie <strong>très fréquente</strong>, dont la <span class=\"kw-def\">prévalence</span> est <strong>en augmentation</strong> du fait du vieillissement de la population.</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Chiffres à retenir</h4>\n      <ul>\n        <li>Touche <span class=\"kw-chiffre\">≥ 1/5 des patients de &gt; 65 ans</span></li>\n        <li>Touche <span class=\"kw-chiffre\">2/3 des patients de &gt; 85 ans</span></li>\n        <li>La <span class=\"kw-ttt\">chirurgie</span> de la cataracte est la <strong>chirurgie la plus fréquente toutes spécialités confondues</strong> : environ <span class=\"kw-chiffre\">800 000/an</span> en France</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Implication pratique.</strong> Toute BAV progressive bilatérale chez un sujet &gt;<span class=\"kw-chiffre\"> 65 ans</span> doit faire évoquer en 1ʳᵉ intention une cataracte (très fréquente, accessible à un traitement chirurgical efficace), <em>sans pour autant oublier <span class=\"kw-clinique\">les</span> pathologies maculaires associées</em> : DMLA, glaucome chronique, maculopathies diabétiques peuvent <strong>coexister</strong> chez le même patient.\n      </div>","frequence":0},{"id":"81-11","rang":"B","rubrique":"Étiologies","titre":"Connaître les grandes familles médicamenteuses à l’origine d’une altération chronique de la vision","contenu":"<p><span class=\"kw-clinique\">Les</span> <span class=\"kw-def\">maculopathies toxiques</span> peuvent se présenter sous un mode <strong>aigu</strong> ou <strong>insidieux</strong>, souvent dans le cadre d’un <span class=\"kw-clinique\">syndrome maculaire</span> (BAV, scotome central ou paracentral, métamorphopsies, <span class=\"kw-clinique\">dyschromatopsie bleu-jaune</span>). L’atteinte est <strong>le plus souvent bilatérale</strong>. L’<span class=\"kw-clinique\">interrogatoire est l’étape clé</span> du <span class=\"kw-def\">diagnostic étiologique</span> (toxiques, exposition professionnelle, médicaments).</p>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\"><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> g</span>randes familles à connaître pour l’EDN</h4>\n      <table >\n        <thead><tr><th>Famille</th><th>Mécanisme / contexte</th><th>Caractéristiques de l’atteinte</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Antipaludéens de synthèse (APS)</strong></span><br>chloroquine, <strong><span class=\"kw-ttt\">hydroxychloroquine</span></strong></td>\n            <td>Accumulation de métabolites toxiques dans l’épithélium p<span class=\"kw-chiffre\">igm</span>entaire. Risque <span class=\"kw-alerte\">supérieur avec la chloroquine</span> (dose cumulée &gt;<span class=\"kw-chiffre\"> 460 g</span>) qu’avec l’<span class=\"kw-ttt\">hydroxychloroquine</span> (dose cumulée &gt;<span class=\"kw-chiffre\"> 1000 g</span>). La grande majorité des patients est aujourd’hui sous <span class=\"kw-ttt\">hydroxychloroquine</span> ✅.</td>\n            <td>Risque de rétinopathie <span class=\"kw-etio\">toxique</span> bilatérale <span class=\"kw-alerte\">potentiellement cécitante et irréversible</span>. Délai sous <span class=\"kw-ttt\">hydroxychloroquine</span> : <span class=\"kw-chiffre\">≥ 5 ans de prise continue</span> (sauf pathologie rétinienne sous-jacente ou <span class=\"kw-etio\">obésité</span> — APS stockés dans la <span class=\"kw-clinique\">masse</span> adipeuse). <span class=\"kw-def\">Stade</span> évolué : maculopathie « en œil de bœuf ».</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Inhibiteurs MEK</strong></span></td>\n            <td>Voie MAPK intracellulaire — utilisés en oncologie (<span class=\"kw-clinique\">mélanomes métastatiques</span> ++).</td>\n            <td>Symptômes oculaires <strong>aigus</strong> ou rapidement progressifs. Atteinte la plus fréquente : <span class=\"kw-clinique\">décollements séreux rétiniens</span> multiples (réversibles à l’arrêt ou à la diminution). Plus rare et grave : <span class=\"kw-alerte\">occlusion de la veine centrale de la rétine</span>.</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-ttt\"><strong>Nitrite d’alkyle (« poppers »)</strong></span></td>\n            <td>Anciennement <span class=\"kw-clinique\">angor</span> (vasodilatateurs, abandonnés au profit de la <span class=\"kw-ttt\">trinitrine</span>). <strong>Mésusage récréatif</strong> aujourd’hui (euphorie, stimulation sexuelle).</td>\n            <td>Affection <strong>rare</strong>. Survient de manière aiguë <em>quelle que soit la chronicité de la prise</em>. BAV avec phosphènes et microscotome central.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;color:#1f2937;\">Mention spéciale — <span class=\"kw-ttt\">corticoïdes</span> au long cours</h4>\n      <ul>\n        <li><span class=\"kw-clinique\">Les</span> <span class=\"kw-ttt\">corticoïdes locaux ou généraux au long cours</span> sont à l’origine d’une <span class=\"kw-clinique\">cataracte iatrogène</span> de forme <strong>sous-capsulaire postérieure</strong> (voir obj. dédié à la cataracte).</li>\n        <li>Mécanisme distinct des maculopathies toxiques, mais à connaître comme cause médicamenteuse classique de BAV chronique.</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>Prévention APS — <span class=\"kw-def\">surveillance</span> ophtalmologique obl<span class=\"kw-chiffre\">iga</span>toire.</strong> Bilan ophtalmologique = <span class=\"kw-clinique\">FO + champ visuel automatisé des 10° centraux + ERG multifocal (ou OCT, ou cliché FO en autofluorescence)</span>. Réalisé <strong>avant la mise en place du traitement</strong> (examen de référence), puis au cours du <span class=\"kw-def\">suivi</span> à un rythme adapté. Devant <span class=\"kw-clinique\">les</span> premiers signes (scotomes juxtamaculaires, diminution des réponses périfovéolaires en ERG mfERG) → <span class=\"kw-alerte\">arrêt immédiat du traitement</span>, sachant que les mécanismes toxiques peuvent se poursuivre jusqu’à<span class=\"kw-chiffre\"> 6 mois</span> après l’arrêt.\n      </div>\n\n      <div class=\"callout callout-info\">\n        <strong>CAT générale.</strong> Le traitement passe avant tout par l’<strong>arrêt de la substance</strong> en cause. Cet arrêt doit être discuté avec le prescripteur initial lorsqu’aucune alternative thérapeutique ne peut être proposée (oncologie, maladies de système…).\n      </div>","frequence":1}],"astuces":[],"strategie":{"urgence":"<p><strong>Le plus souvent non urgent :</strong> la <span class=\"kw-def\">BAV chronique progressive</span> (cataracte, DMLA atrophique, dystrophies) relève d'une prise en charge programmée.<br><strong><span class=\"kw-alerte\">Urgence</span> < 48 h :</strong> une <span class=\"kw-alerte\">BAV brutale chez un patient porteur de drusen</span> impose un <span class=\"kw-clinique\">examen ophtalmologique en urgence</span> (délai <span class=\"kw-chiffre\">< 48 h</span>) pour dépister des <span class=\"kw-etio\">néovaisseaux choroïdiens</span>.<br><strong>Urgence thérapeutique :</strong> <span class=\"kw-etio\">néovaisseaux choroïdiens</span> (DMLA exsudative) → <span class=\"kw-ttt\">injections intravitréennes d'anti-VEGF</span> sans délai pour limiter les séquelles visuelles.<br><strong>Endophtalmie post-cataracte (<span class=\"kw-chiffre\">J2–J7</span>) :</strong> <span class=\"kw-alerte\">infection intraoculaire sévère</span> → <span class=\"kw-ttt\">antibiothérapie intravitréenne + générale</span> ± <span class=\"kw-ttt\">vitrectomie</span>.<br><strong>Maculopathie toxique aux APS :</strong> <span class=\"kw-ttt\">arrêt immédiat</span> du traitement dès les premiers signes (toxicité pouvant se poursuivre jusqu'à <span class=\"kw-chiffre\">6 mois</span> après l'arrêt).</p>","hospit":"<p><strong>Parcours ambulatoire :</strong> la quasi-totalité de la prise en charge est <span class=\"kw-clinique\">ophtalmologique externe</span> (consultation, <span class=\"kw-imagerie\">fond d'œil</span>, <span class=\"kw-imagerie\">OCT</span>, injections).<br><strong><span class=\"kw-ttt\">Chirurgie</span> de cataracte :</strong> <span class=\"kw-ttt\">chirurgie ambulatoire</span> sous <span class=\"kw-ttt\">anesthésie topique</span>, après consultation pré-anesthésique programmée dans le mois précédent.<br><strong>Anti-VEGF :</strong> <span class=\"kw-ttt\">injections intravitréennes répétées</span> en <span class=\"kw-clinique\">consultation externe</span>, en conditions d'<span class=\"kw-clinique\">asepsie oculaire</span> sous anesthésie topique.<br><strong>BAV brutale sur drusen :</strong> <span class=\"kw-alerte\">adressage ophtalmologique en urgence (< 48 h)</span>.<br><strong>Malvoyance / échec thérapeutique :</strong> <span class=\"kw-ttt\">rééducation orthoptique</span> + <span class=\"kw-ttt\">aides visuelles grossissantes</span>, idéalement en équipe pluridisciplinaire.</p>","redflags":"<ul><li><span class=\"kw-alerte\">BAV brutale unilatérale</span> avec <span class=\"kw-clinique\">métamorphopsies</span> chez un patient porteur de <span class=\"kw-etio\">drusen</span> → suspicion de <span class=\"kw-etio\">néovaisseaux choroïdiens</span> (DMLA exsudative)</li><li><span class=\"kw-clinique\">Scotome central</span> profond ou <span class=\"kw-clinique\">métamorphopsies</span> à la <span class=\"kw-clinique\">grille d'Amsler</span> (syndrome maculaire)</li><li><span class=\"kw-alerte\">Hématome maculaire</span> compliquant une <span class=\"kw-etio\">DMLA exsudative</span> (récupération visuelle le plus souvent impossible)</li><li><span class=\"kw-alerte\">Endophtalmie</span> après <span class=\"kw-ttt\">chirurgie</span> de cataracte : BAV + inflammation entre <span class=\"kw-chiffre\">J2 et J7</span></li><li>Maculopathie aux <span class=\"kw-ttt\">antipaludéens de synthèse</span> en « <span class=\"kw-radio\">œil de bœuf</span> » : atteinte <span class=\"kw-alerte\">irréversible</span> si poursuite du traitement</li><li>Rétinopathie p<span class=\"kw-chiffre\">igm</span>entaire évoluée : <span class=\"kw-clinique\">champ visuel tubulaire</span> → risque de <span class=\"kw-alerte\">cécité</span></li></ul>","principes":"<p>La prise en charge est <span class=\"kw-def\">étiologique</span> : chaque cause d'altération chronique de la vision a son traitement propre.</p><p><strong>Cataracte</strong></p><p>Indication chirurgicale : <span class=\"kw-clinique\">gêne fonctionnelle</span> du patient, <span class=\"kw-clinique\">fond d'œil inaccessible</span>, ou prévention des complications de la cataracte</p><ul><li>Traitement <span class=\"kw-ttt\">exclusivement chirurgical</span> : aucun traitement médical, préventif ni curatif</li><li><span class=\"kw-ttt\">Extraction extracapsulaire par phacoémulsification</span> + <span class=\"kw-ttt\">implant intraoculaire de chambre postérieure</span>, en ambulatoire sous anesthésie topique</li><li>Récupération fonctionnelle excellente et rapide (nouvelle correction <span class=\"kw-chiffre\">~1 mois</span> après), sauf pathologie oculaire associée</li></ul><p><strong>DMLA exsudative (néovasculaire)</strong></p><p>Toute <span class=\"kw-alerte\">BAV brutale sur drusen</span> → examen en <span class=\"kw-alerte\">urgence</span> <span class=\"kw-chiffre\">< 48 h</span> pour traiter les néovaisseaux</p><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-ttt\">injections intravitréennes d'anti-VEGF</span> (ranibizumab, aflibercept, brolucizumab, faricimab)</li><li>Rythme proactif : intervalle minimal <span class=\"kw-chiffre\">4 semaines</span>, maximal <span class=\"kw-chiffre\">4–5 mois</span></li><li><span class=\"kw-ttt\">Thérapie photodynamique</span> (vertéporfine) en 2e intention dans certains cas</li></ul><p><strong>DMLA atrophique (sèche)</strong></p><ul><li>Stade débutant (MLA, <span class=\"kw-etio\">drusen</span>) : <span class=\"kw-ttt\">supplémentation</span> vitamine E, vitamine C, zinc, lutéine, zéaxanthine (retarde l'évolution)</li><li><span class=\"kw-ttt\">Conseils alimentaires</span> : régime méditerranéen (légumes verts, poisson, huile d'olive)</li><li>Pas de bénéfice des <span class=\"kw-ttt\">oméga-3 ni du bêta-carotène</span> sur la progression</li><li>Nouveaux <span class=\"kw-ttt\">anti-complément C3/C5 en intravitréen</span> : ralentissent l'atrophie (agrément FDA <span class=\"kw-chiffre\">2023</span>, indications à préciser)</li></ul><p><strong>Œdème maculaire</strong></p><ul><li><span class=\"kw-ttt\">Traitement de la cause</span> : équilibre d'une <span class=\"kw-etio\">HTA</span> / d'un <span class=\"kw-etio\">diabète</span>, traitement d'une <span class=\"kw-etio\">uvéite</span></li><li><span class=\"kw-ttt\">Anti-VEGF</span> et/ou <span class=\"kw-ttt\">corticoïdes en intravitréen</span> selon l'étiologie</li><li>Œdème d'<span class=\"kw-etio\">Irvine-Gass</span> post-cataracte (<span class=\"kw-chiffre\">3 %</span>) : <span class=\"kw-ttt\">AINS + corticoïdes locaux</span> + <span class=\"kw-ttt\">acétazolamide</span></li><li>Maculopathie diabétique : <span class=\"kw-ttt\">photocoagulation au laser focal</span> possible</li></ul><p><strong>Maculopathies toxiques</strong></p><ul><li><span class=\"kw-ttt\">Arrêt du toxique</span> en cause : <span class=\"kw-etio\">antipaludéens de synthèse</span>, <span class=\"kw-etio\">inhibiteurs MEK</span>, <span class=\"kw-etio\">poppers</span></li><li>Arrêt à discuter avec le prescripteur initial si aucune alternative thérapeutique</li><li>APS : <span class=\"kw-ttt\">arrêt immédiat</span> dès les premiers signes, sinon atteinte <span class=\"kw-alerte\">irréversible</span> en « œil de bœuf »</li></ul><p><strong>Syndromes de l'interface vitréomaculaire</strong></p><ul><li>Membrane épimaculaire / trou maculaire confirmés par <span class=\"kw-imagerie\">OCT maculaire</span></li><li>Si BAV importante : <span class=\"kw-ttt\">pelage de la membrane</span> par <span class=\"kw-ttt\">vitrectomie</span></li><li>Trou maculaire : <span class=\"kw-ttt\">vitrectomie</span> selon la taille du trou</li></ul>","suivi":"<p><strong>Après <span class=\"kw-ttt\">chirurgie</span> de cataracte :</strong> <span class=\"kw-ttt\">collyres anti-inflammatoire + antibiotique ~1 mois</span>, patient revu <span class=\"kw-chiffre\">≥ 2 fois</span> dans le mois (1re semaine puis <span class=\"kw-chiffre\">1 mois</span>).<br><strong>À surveiller en post-op :</strong> <span class=\"kw-alerte\">endophtalmie (J2–J7)</span> et <span class=\"kw-etio\">opacification de la capsule postérieure</span> (<span class=\"kw-chiffre\">~50 % à 2 ans</span> → <span class=\"kw-ttt\">capsulotomie au laser YAG</span>).<br><strong>DMLA exsudative :</strong> <span class=\"kw-ttt\">injections d'anti-VEGF répétées</span> avec <span class=\"kw-def\">suivi</span> <span class=\"kw-imagerie\">OCT</span> ; risque de <span class=\"kw-alerte\">bilatéralisation de 50 % à 5 ans</span>.<br><strong>Auto-<span class=\"kw-def\">surveillance</span> DMLA :</strong> <span class=\"kw-clinique\">grille d'Amsler</span> pour dépister une conversion néovasculaire.<br><strong>Antipaludéens de synthèse :</strong> bilan ophtalmologique (<span class=\"kw-imagerie\">fond d'œil</span> + <span class=\"kw-clinique\">champ visuel automatisé</span> + <span class=\"kw-imagerie\">ERG multifocal / OCT / autofluorescence</span>) avant le traitement (examen de référence) puis suivi régulier.</p>"},"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Altération chronique de la vision (BAV progressive) — 1re étape : lampe à fente après dilatation pupillaire","detail":"<h4>CAT — Altération chronique de la vision — Orientation diagnostique devant une baisse d'acuité visuelle progressive</h4>","branches":[{"to":"t-cataracte","label":"Opacité du cristallin (LAF)","color":"green"},{"to":"q-fo","label":"Milieux transparents → fond d'œil","color":"blue"}]},{"id":"t-cataracte","kind":"terminal","label":"Cataracte — Opacification du cristallin","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV progressive bilatérale</span>, prédominant de loin, avec <span class=\"kw-clinique\">myopie d'indice</span></li><li><span class=\"kw-clinique\">Photophobie</span> avec halos colorés ; diagnostic <span class=\"kw-def\">clinique</span>, aucun examen complémentaire nécessaire</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> : phacoémulsification + <span class=\"kw-ttt\">implant intraoculaire</span>, en ambulatoire</li><li>Indication : <span class=\"kw-clinique\">gêne fonctionnelle</span>, <span class=\"kw-imagerie\">fond d'œil</span> inaccessible ou prévention des complications</li></ul>"},{"id":"q-fo","kind":"decision","label":"Localisation de l'atteinte au fond d'œil ? — OCT maculaire si syndrome maculaire (BAV + scotome central + métamorphopsies)","branches":[{"to":"t-glaucome","label":"Atteinte du nerf optique","color":"amber"},{"to":"t-dystrophie","label":"Rétine périphérique (héméralopie, CV tubulaire)","color":"blue"},{"to":"q-macula","label":"Macula (syndrome maculaire)","color":"blue"}]},{"id":"t-glaucome","kind":"terminal","label":"Glaucome chronique à angle ouvert évolué — Atteinte du nerf optique — voir item 84","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV souvent bilatérale</span>, tardive (<span class=\"kw-def\">stade</span> évolué)</li></ul><h4>Conduite</h4><ul><li>Prise en charge spécialisée — <span class=\"kw-etio\">renvoi item 84</span></li></ul>"},{"id":"t-dystrophie","kind":"terminal","label":"Dystrophie rétinienne héréditaire — Atteinte périphérique ou maculaire, souvent bilatérale","color":"blue","detail":"<h4>Clinique</h4><ul><li>Rétinopathie p<span class=\"kw-chiffre\">igm</span>entaire : <span class=\"kw-clinique\">héméralopie</span> + <span class=\"kw-clinique\">rétrécissement du champ visuel</span> dès l'enfance</li><li><span class=\"kw-def\">Stade</span> évolué : <span class=\"kw-clinique\">champ visuel tubulaire</span>, risque de <span class=\"kw-alerte\">cécité</span></li><li>Maladie de Stargardt : <span class=\"kw-clinique\">BAV bilatérale</span> de l'enfance, <span class=\"kw-radio\">maculopathie en œil de bœuf</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">Fond d'œil</span> : <span class=\"kw-radio\">migrations pigmentaires en pseudo-ostéoblastes</span> (rétinopathie p<span class=\"kw-chiffre\">igm</span>entaire)</li></ul>"},{"id":"q-macula","kind":"decision","label":"Orientation devant un syndrome maculaire — OCT maculaire + latéralité + interrogatoire","branches":[{"to":"t-dmla-exsudative","label":"BAV brutale unilat. + drusen (néovaisseaux)","color":"red"},{"to":"t-dmla-atrophique","label":"BAV progressive bilat. + atrophie de l'EP","color":"amber"},{"to":"t-interface","label":"OCT : membrane / trou maculaire","color":"amber"},{"to":"t-oedeme","label":"OCT : œdème maculaire + contexte (diabète, OVCR, post-op, uvéite)","color":"amber"},{"to":"t-toxique","label":"Bilatéral + interrogatoire toxique (APS, iMEK, poppers)","color":"amber"}]},{"id":"t-dmla-exsudative","kind":"terminal","label":"DMLA exsudative — URGENCE — Néovaisseaux choroïdiens","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV brutale, indolore, unilatérale</span> + <span class=\"kw-clinique\">métamorphopsies</span></li><li>Survenue chez un patient porteur de <span class=\"kw-etio\">drusen</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">OCT maculaire</span> : <span class=\"kw-clinique\">œdème</span>, liquide intra/sous-rétinien, décollement de l'EP</li><li><span class=\"kw-imagerie\">Angiographie / OCT-A</span> : néovascularisation choroïdienne</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-alerte\">Urgence thérapeutique</span> : <span class=\"kw-ttt\">anti-VEGF en intravitréen</span> sans délai</li><li><span class=\"kw-ttt\">Thérapie photodynamique</span> en <span class=\"kw-chiffre\">2e intention</span> dans certains cas</li></ul><h4>Délai</h4><ul><li>Examen ophtalmologique en <span class=\"kw-chiffre\">urgence (< 48 h)</span> devant toute BAV brutale sur drusen</li></ul>"},{"id":"t-dmla-atrophique","kind":"terminal","label":"DMLA atrophique (sèche) — Atrophie de l'épithélium pigmentaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV progressive bilatérale</span> de loin et de près</li><li><span class=\"kw-clinique\">Évolution</span> lente mais <span class=\"kw-alerte\">inexorable</span> vers un scotome central</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">OCT</span> : atrophie de l'EP ; <span class=\"kw-imagerie\">FO en autofluorescence</span> : plages sombres</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Supplémentation</span> (vitamines C/E, zinc, lutéine, zéaxanthine) + régime méditerranéen</li><li><span class=\"kw-ttt\">Anti-complément C3/C5 en intravitréen</span> : ralentissent l'atrophie (indications à préciser)</li></ul>"},{"id":"t-interface","kind":"terminal","label":"Syndrome de l'interface vitréomaculaire — Membrane épimaculaire / trou maculaire","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV</span> et/ou <span class=\"kw-clinique\">métamorphopsies</span> ; trou maculaire : <span class=\"kw-clinique\">scotome central</span></li><li>Atteinte souvent unilatérale</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">OCT maculaire</span> confirme le diagnostic et pose l'indication chirurgicale</li><li>Membrane : <span class=\"kw-radio\">reflet cellophane</span> ; trou : <span class=\"kw-radio\">lésion orangée arrondie à bords nets</span></li></ul><h4>Traitement</h4><ul><li>Si BAV importante : <span class=\"kw-ttt\">pelage de la membrane</span> / <span class=\"kw-ttt\">vitrectomie</span></li></ul>"},{"id":"t-oedeme","kind":"terminal","label":"Œdème maculaire — Diabète · OVCR · post-cataracte · uvéite","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">BAV progressive</span> + <span class=\"kw-clinique\">métamorphopsies</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">OCT</span> : kystes intrarétiniens ; <span class=\"kw-imagerie\">fond d'œil</span> : <span class=\"kw-clinique\">œdème</span> cystoïde en <span class=\"kw-radio\">pétales de fleur</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Traitement de la cause</span> (équilibre <span class=\"kw-etio\">HTA</span>/diabète, traitement de l'uvéite)</li><li><span class=\"kw-ttt\">Anti-VEGF</span> ± <span class=\"kw-ttt\">corticoïdes en intravitréen</span> selon l'étiologie</li><li>Irvine-Gass : <span class=\"kw-ttt\">AINS + corticoïdes locaux + acétazolamide</span></li></ul>"},{"id":"t-toxique","kind":"terminal","label":"Maculopathie toxique — APS · inhibiteurs MEK · poppers","color":"amber","detail":"<h4>Clinique</h4><ul><li>Atteinte <span class=\"kw-clinique\">bilatérale</span> : scotome central, métamorphopsies, dyschromatopsie bleu-jaune</li><li><span class=\"kw-def\">Interrogatoire</span> : toxiques, exposition professionnelle, médicaments</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Arrêt du toxique</span> en cause (à discuter avec le prescripteur si pas d'alternative)</li><li>APS : <span class=\"kw-ttt\">arrêt immédiat</span> dès <span class=\"kw-clinique\">les</span> premiers signes (toxicité jusqu'à <span class=\"kw-chiffre\">6 mois</span> après l'arrêt)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li>APS : bilan <span class=\"kw-imagerie\">FO + champ visuel + ERG multifocal/OCT</span> avant puis pendant le traitement</li></ul>"}]},"cards":[{"i":"0b632b78e06c","n":81,"o":"81-6","u":"Définition","t":"Connaître la définition de la dégénérescence maculaire liée à l’âge (DMLA)","q":"Quelle est la définition de la dégénérescence maculaire liée à l'âge (DMLA) ?","a":"<p>La DMLA est une <strong>affection rétinienne dégénérative</strong> qui touche spécifiquement la <strong>région maculaire</strong> chez les patients de <strong>plus de 50 ans</strong>.</p>"},{"i":"2e8a35b1f8a7","n":81,"o":"81-6","u":"Définition","t":"Connaître la définition de la dégénérescence maculaire liée à l’âge (DMLA)","q":"Quelles sont les deux formes évoluées principales de la dégénérescence maculaire liée à l'âge (DMLA) ?","a":"<ul><li>La forme <strong>atrophique</strong> (ou « sèche ») : caractérisée par une disparition progressive des cellules de l'épithélium pigmentaire rétinien (EP) et des photorécepteurs sus-jacents.</li><li>La forme <strong>exsudative</strong> ou néovasculaire (ou « humide ») : caractérisée par le développement de néovaisseaux choroïdiens sous l'EP ou sous la rétine maculaire.</li></ul>"},{"i":"b9ee37a4ab41","n":81,"o":"81-6","u":"Définition","t":"Connaître la définition de la dégénérescence maculaire liée à l’âge (DMLA)","q":"Quelle est la prévalence de la dégénérescence maculaire liée à l'âge (DMLA) et son impact en France ?","a":"<p>La DMLA est la <strong>première cause de malvoyance</strong> après 50 ans dans les pays industrialisés. Sa prévalence globale est de <strong>0,5%</strong> après 50 ans, mais elle peut atteindre <strong>10%</strong> après 85 ans.</p>"},{"i":"2f47ceba5e89","n":81,"o":"81-9","u":"Définition","t":"Connaître la définition de la cataracte, ses principales causes, et les modalités de diagnostic clinique","q":"Quelle est la définition de la cataracte ?","a":"<p>La cataracte est une <strong>opacification</strong> de tout ou partie du <strong>cristallin</strong>.</p>"},{"i":"6fd636348a89","n":81,"o":"81-9","u":"Définition","t":"Connaître la définition de la cataracte, ses principales causes, et les modalités de diagnostic clinique","q":"Quels sont les différents types de cataracte observables à la lampe à fente et leurs spécificités cliniques et étiologiques ?","a":"<ul><li><strong>Nucléaire</strong> : opacification du noyau cristallinien. Caractérisée par une BAV de loin et une <strong>myopie d'indice</strong>. Étiologie typique : <strong>liée à l'âge</strong>.</li><li><strong>Corticale</strong> : opacification en \"cavaliers\" en périphérie du cortex. Entraîne peu de BAV, mais éblouissement et photophobie.</li><li><strong>Sous-capsulaire postérieure</strong> : opacification en soucoupe. Cause une gêne de <strong>loin et de près</strong>. Étiologies : métabolique, iatrogène, traumatisme par contusion.</li><li><strong>Totale</strong> : cataracte très évoluée, avec une aire pupillaire blanche visible à l'œil nu.</li></ul>"},{"i":"b786bd5b710a","n":81,"o":"81-9","u":"Définition","t":"Connaître la définition de la cataracte, ses principales causes, et les modalités de diagnostic clinique","q":"Comment établit-on le diagnostic clinique de la cataracte et quels sont les signes fonctionnels caractéristiques ?","a":"<p>Le diagnostic de cataracte est <strong>exclusivement clinique</strong> et ne requiert pas d'examen complémentaire en première intention. L'examen clé est la <strong>lampe à fente après dilatation pupillaire</strong>, qui objective l'opacification cristallinienne.</p><p>Les signes fonctionnels incluent :</p><ul><li><strong>Baisse d'acuité visuelle (BAV) progressive</strong>, bilatérale (prédomine en vision de loin, mais la vision de près reste longtemps conservée, sauf si cataracte sous-capsulaire postérieure).</li><li><strong>Myopie d'indice</strong> paradoxale (le patient lit à nouveau sans lunettes).</li><li>Diplopie monoculaire (plus rare, dans la cataracte nucléaire).</li><li>Modification de la perception des couleurs (jaunissement).</li><li>Photophobie avec <strong>halos colorés</strong> autour des lumières.</li></ul>"},{"i":"f35b9a89cf49","n":81,"o":"81-9","u":"Définition","t":"Connaître la définition de la cataracte, ses principales causes, et les modalités de diagnostic clinique","q":"Quelles sont les principales causes de cataracte à connaître pour l'EDN ?","a":"<ul><li><strong>Sénile (âge)</strong> : la plus fréquente.</li><li><strong>Traumatique</strong> : contusion (aspect en rosace) ou perforant.</li><li><strong>Ophtalmologique</strong> : uvéite chronique, myopie forte, rétinopathies pigmentaires, antécédent de chirurgie oculaire.</li><li><strong>Métabolique</strong> : diabète, hypoparathyroïdie, hypercorticisme, hypocalcémie chronique.</li><li><strong>Iatrogène</strong> : corticoïdes locaux ou généraux au long cours (forme sous-capsulaire postérieure), radiothérapie orbitaire.</li><li><strong>Génétique</strong> : Trisomie 21, dystrophie myotonique de Steinert.</li><li><strong>Congénital</strong> : embryofoetopathie (rubéole congénitale), héréditaires.</li></ul>"}]};